-- =====================================================
-- NMO Members — initial seed
-- Generated from browser-console scrape across the community
-- members page + post pagination.
--
-- 529 unique members, all with display_name + avatar_url.
--
-- Safe to re-run: ON CONFLICT keeps the most-complete value of each
-- column (won't NULL out a populated field with a partial row).
--
-- Run the engagement.sql migration FIRST so nmo_members exists.
-- =====================================================

on conflict (handle) do update
  set display_name = coalesce(excluded.display_name, public.nmo_members.display_name),
      avatar_url   = coalesce(excluded.avatar_url, public.nmo_members.avatar_url),
      level        = coalesce(excluded.level, public.nmo_members.level),
      last_seen_at = now();
